import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.B5WAEDB7.js";const b=JSON.parse('{"title":"认证","description":"","frontmatter":{},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md","lastUpdated":1786258560000}'),s={name:"guide/authentication.md"};function c(i,t,r,n,h,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h1><p>认证解决「你是谁」。这一章讲令牌怎么签发与校验、密码怎么存、第三方登录与二次验证怎么接、会话失效怎么表达。</p><p>「你能做什么」在 <a href="./authorization">授权</a>。</p><h2 id="在管道里的位置" tabindex="-1">在管道里的位置 <a class="header-anchor" href="#在管道里的位置" aria-label="Permalink to &quot;在管道里的位置&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>… → UseAuthentication → 租户解析 → 会话闸门 → UseAuthorization → 端点</span></span>\n<span class="line"><span>      ↑ 你是谁              ↑ 哪个租户   ↑ 会话还有效吗  ↑ 你能做什么</span></span></code></pre></div><p>顺序有讲究：租户解析要读令牌里的租户 claim，所以排在认证之后；授权判定要在租户上下文里进行，所以排在租户解析之后。</p><h2 id="安装与启用" tabindex="-1">安装与启用 <a class="header-anchor" href="#安装与启用" aria-label="Permalink to &quot;安装与启用&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XiHan.Framework.Authentication</span></span></code></pre></div><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DependsOn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XiHanAuthenticationModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MyAppModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XiHanModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { }</span></span></code></pre></div><p>包内分六块：<code>Jwt</code>（令牌）、<code>Users</code>（认证流程与用户存储）、<code>OAuth</code>（第三方登录）、<code>Oidc</code>（OIDC 签发）、<code>Otp</code>（TOTP）、<code>OneTimeCode</code>（一次性验证码）。</p><h2 id="jwt-令牌" tabindex="-1">JWT 令牌 <a class="header-anchor" href="#jwt-令牌" aria-label="Permalink to &quot;JWT 令牌&quot;">​</a></h2><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>配置节 <code>XiHan:Authentication:Jwt</code>：</p><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>SecretKey</code></td><td>—</td><td>签名密钥。<strong>生产务必改为高强度随机值</strong>，走环境变量或密钥库</td></tr><tr><td><code>Issuer</code> / <code>Audience</code></td><td>—</td><td>签发者 / 受众，校验时比对</td></tr><tr><td><code>AccessTokenExpirationMinutes</code></td><td><code>60</code></td><td>访问令牌有效期</td></tr><tr><td><code>RefreshTokenExpirationDays</code></td><td><code>7</code></td><td>刷新令牌有效期</td></tr><tr><td><code>ClockSkewMinutes</code></td><td><code>5</code></td><td>允许的时钟偏差，多节点部署必需</td></tr></tbody></table><h3 id="ijwttokenservice" tabindex="-1"><code>IJwtTokenService</code> <a class="header-anchor" href="#ijwttokenservice" aria-label="Permalink to &quot;`IJwtTokenService`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>成员</th><th>说明</th></tr></thead><tbody><tr><td><code>GenerateAccessToken(List&lt;Claim&gt;)</code></td><td>签发访问令牌，返回 <code>JwtTokenResult</code></td></tr><tr><td><code>GenerateRefreshToken()</code></td><td>生成刷新令牌（不透明随机串）</td></tr><tr><td><code>ValidateToken(string)</code></td><td>校验并返回 <code>ClaimsPrincipal</code>，失败返回 <code>null</code></td></tr><tr><td><code>GetClaimsFromToken(string)</code></td><td>取出 Claim 列表</td></tr><tr><td><code>IsTokenExpired(string)</code></td><td>是否已过期</td></tr><tr><td><code>RefreshAccessToken(accessToken, refreshToken)</code></td><td>用旧访问令牌 + 刷新令牌换新的一套</td></tr></tbody></table><p>刷新令牌的持久化走 <code>IRefreshTokenStore</code>——框架给了默认实现，需要落库时 <code>Replace</code> 掉。</p><div class="tip custom-block"><p class="custom-block-title">别把权限码冻结进令牌</p><p>把权限清单写进 JWT 有两个后果：授予或回收后要等令牌过期才生效；权限清单随令牌一起泄露。</p><p>推荐只放<strong>身份信息</strong>（用户、会话、租户、角色），权限交给服务端实时判定——判定可以走缓存快照，性能不是问题。见 <a href="./authorization">授权</a>。</p></div><div class="warning custom-block"><p class="custom-block-title">刷新端点必须匿名</p><p>访问令牌过期后再带着它去刷新，如果刷新端点本身要求认证就永远进不去。刷新端点应当 <code>[AllowAnonymous]</code>，并<strong>同时校验旧访问令牌与刷新令牌</strong>——两者成对才算合法。</p></div><h2 id="密码" tabindex="-1">密码 <a class="header-anchor" href="#密码" aria-label="Permalink to &quot;密码&quot;">​</a></h2><h3 id="哈希算法" tabindex="-1">哈希算法 <a class="header-anchor" href="#哈希算法" aria-label="Permalink to &quot;哈希算法&quot;">​</a></h3><p>配置节 <code>XiHan:Authentication:PasswordHasher</code>，算法是 <strong>PBKDF2</strong>：</p><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>Version</code></td><td><code>1</code></td><td>方案版本号，参数升级后老密码仍按旧版本校验</td></tr><tr><td><code>Iterations</code></td><td><code>600000</code></td><td>迭代次数，OWASP 对 PBKDF2-SHA256 的推荐量级</td></tr><tr><td><code>SaltSize</code></td><td><code>32</code></td><td>盐长度（字节）</td></tr><tr><td><code>HashSize</code></td><td><code>32</code></td><td>输出长度（字节）</td></tr><tr><td><code>HashAlgorithm</code></td><td><code>SHA256</code></td><td>哈希算法</td></tr></tbody></table><p>存储格式是自描述串：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>version:iterations:algorithm:base64(salt):base64(hash)</span></span></code></pre></div><p>自描述的好处是<strong>参数可以随时调大而不影响存量密码</strong>——每条哈希都记着自己是用什么参数算的。校验用定长比较抵抗时序攻击；参数变更后 <code>NeedsRehash</code> 会提示该密码需要在下次登录成功时透明重算。</p><h3 id="认证流程" tabindex="-1">认证流程 <a class="header-anchor" href="#认证流程" aria-label="Permalink to &quot;认证流程&quot;">​</a></h3><p><code>IAuthenticationService</code> 是认证主流程的门面：</p><table tabindex="0"><thead><tr><th>方法</th><th>用途</th></tr></thead><tbody><tr><td><code>AuthenticateAsync(username, password)</code></td><td>主认证，返回 <code>AuthenticationResult</code></td></tr><tr><td><code>ValidatePasswordStrengthAsync(password, customBlacklist?)</code></td><td>密码强度校验</td></tr><tr><td><code>ChangePasswordAsync</code> / <code>ResetPasswordAsync</code></td><td>改密 / 重置</td></tr><tr><td><code>EnableTwoFactorAuthenticationAsync</code> / <code>DisableTwoFactorAuthenticationAsync</code></td><td>开关二次验证</td></tr><tr><td><code>VerifyTwoFactorCodeAsync</code></td><td>校验二次验证码</td></tr><tr><td><code>GenerateRecoveryCodesAsync</code> / <code>VerifyRecoveryCodeAsync</code></td><td>恢复码</td></tr><tr><td><code>RecordFailedLoginAttemptAsync</code></td><td>记录失败尝试（锁定与风控的输入）</td></tr></tbody></table><p>用户数据的读写走 <code>IUserStore</code>——框架只定义契约，<strong>业务侧必须 <code>Replace</code> 成自己的实现</strong>（通常是数据库）。</p><h2 id="一次性验证码" tabindex="-1">一次性验证码 <a class="header-anchor" href="#一次性验证码" aria-label="Permalink to &quot;一次性验证码&quot;">​</a></h2><p><code>IOneTimeCodeService</code> 用于「签发 → 一次性消费」的场景：邮箱/短信登录验证码、改绑联系方式验证码等。</p><p>四条设计特征：</p><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td>加密安全随机</td><td>用 <code>RandomNumberGenerator</code> 生成，不是 <code>Random</code></td></tr><tr><td>存分布式缓存</td><td>状态放 <code>IDistributedCache</code>，宿主接了 Redis 就天然支持多实例</td></tr><tr><td><strong>消费即销毁</strong></td><td><strong>无论校验成功与否，读取后即删除</strong>——杜绝重放与暴力穷举</td></tr><tr><td>可携带负载</td><td>如改绑场景暂存待生效的新邮箱/新手机号，消费成功后取回</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">同「用途 + 目标」重复签发会覆盖旧码</p><p>用途标识（如 <code>auth:email-login</code>）参与存储键隔离。对同一个邮箱重复请求验证码，后一次会把前一次覆盖掉——用户拿旧码来验会失败。前端要做发送频率限制。</p></div><h2 id="第三方登录" tabindex="-1">第三方登录 <a class="header-anchor" href="#第三方登录" aria-label="Permalink to &quot;第三方登录&quot;">​</a></h2><p>配置节 <code>XiHan:Authentication:OAuth</code>：</p><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>Enabled</code></td><td>总开关</td></tr><tr><td><code>FrontendCallbackUrl</code></td><td>第三方授权完成后跳回的前端页面</td></tr><tr><td><code>Providers[]</code></td><td>各提供商配置</td></tr></tbody></table><p>每个 provider 的字段：<code>Name</code>（<strong>内部标识，参与回调路由，不要随意改</strong>）、<code>DisplayName</code>（前端展示名）、<code>Enabled</code>、<code>ClientId</code>、<code>ClientSecret</code>、<code>Scopes[]</code>。</p><p>包内建 <code>github</code> / <code>gitee</code> / <code>google</code> / <code>qq</code> 四个，按同样的结构可以扩展。绑定关系的读写走 <code>IExternalLoginStore</code>。</p><div class="danger custom-block"><p class="custom-block-title">首次第三方登录不要按邮箱并号</p><p>拿第三方返回的邮箱去匹配既有账号并直接登录，等于把「谁控制这个邮箱」的判断外包给了第三方。第三方邮箱未必经过验证，这会成为账号接管的入口。</p><p>安全做法是按 <code>(Provider, ProviderKey)</code> 精确定位；找不到就新建账号，让用户在登录态下主动完成绑定。</p></div><h2 id="totp-二次验证" tabindex="-1">TOTP 二次验证 <a class="header-anchor" href="#totp-二次验证" aria-label="Permalink to &quot;TOTP 二次验证&quot;">​</a></h2><p><code>IOtpService</code> 遵循 RFC 6238：</p><table tabindex="0"><thead><tr><th>成员</th><th>说明</th></tr></thead><tbody><tr><td><code>GenerateTotpSecret()</code></td><td>生成 Base32 密钥</td></tr><tr><td>生成 provisioning URI</td><td>供认证器扫码，形如 <code>otpauth://totp/{issuer}:{account}?secret=...</code></td></tr><tr><td>校验验证码</td><td>带窗口容差，容忍客户端与服务端的时钟差</td></tr></tbody></table><p>TOTP 由认证器本地生成，<strong>服务端不需要下发</strong>——这是它与邮箱/短信验证码在流程上的关键区别：判定需要二次验证时，TOTP 直接等用户输入，邮箱/短信则要先发码。</p><h2 id="会话闸门-401-与-423" tabindex="-1">会话闸门：401 与 423 <a class="header-anchor" href="#会话闸门-401-与-423" aria-label="Permalink to &quot;会话闸门：401 与 423&quot;">​</a></h2><p><code>XiHanSessionStateMiddleware</code> 位于认证之后、授权之前，判定委托给 <code>ISessionStateGate</code>（框架默认实现一律放行）。业务侧 <code>Replace</code> 后可产出两种结果：</p><table tabindex="0"><thead><tr><th>结果</th><th>语义</th><th>客户端该怎么做</th></tr></thead><tbody><tr><td><code>401</code></td><td>会话已失效（登出 / 被踢 / 撤销 / 过期）</td><td>尝试刷新令牌，失败则跳登录页</td></tr><tr><td><strong><code>423</code></strong></td><td><strong>会话被锁定，身份仍然有效</strong></td><td><strong>引导解锁，不是跳登录页</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么框架不定义锁定原因</p><p>锁屏、风控挂起、强制改密、二次验证未完成都可能导致「身份有效但当前不能操作」。框架只提供 <code>423</code> 这个信号位，原因与解锁方式由应用侧定义。</p></div><p>位置也是有讲究的：<strong>在认证之后</strong>（要读 <code>session_id</code> claim）、<strong>在租户解析之后</strong>（会话表通常是多租户实体，租户上下文没解析会被全局过滤器挡掉）、<strong>在授权之前</strong>（<code>423</code> / <code>401</code> 要先于权限评估短路，不能和 <code>403</code> 混淆）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>多节点部署偶发令牌校验失败</td><td>时钟偏差；调大 <code>ClockSkewMinutes</code> 或给节点校时</td></tr><tr><td>刷新令牌一直失败</td><td>刷新端点没设匿名；或没有同时提交旧访问令牌与刷新令牌</td></tr><tr><td>验证码验不过</td><td>已被消费（读取即销毁）；或同目标重复签发把旧码覆盖了</td></tr><tr><td>匿名端点里拿不到用户</td><td>匿名端点不经过认证中间件，<code>ICurrentUser</code> 是空的</td></tr><tr><td>收到 <code>423</code> 却跳了登录页</td><td>客户端把 <code>423</code> 当成 <code>401</code> 处理了</td></tr><tr><td>改了 <code>Iterations</code> 后老用户登录失败</td><td>不应该失败——哈希串自描述，老密码按串里记录的旧参数校验。若真失败，检查是不是连存储格式一起改了</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./authorization">授权</a>：权限码与判定链</li><li><a href="./security">数据加解密</a>：哈希、签名、对称与非对称加密</li><li><a href="./web">Web 应用开发</a>：中间件管道全貌</li><li><a href="./multi-tenancy">多租户</a>：租户解析</li><li><a href="./../packages/authentication">Authentication 包</a>：完整 API 与配置项</li></ul>',54)])])}const u=e(s,[["render",c]]);export{b as __pageData,u as default};
